/**
 * Typed wrappers around the Wails-generated bindings.
 *
 * The generated bindings are plain JavaScript with JSDoc types. This
 * module re-exports them behind a stable, strongly typed surface so the
 * React components never import generated files directly.
 *
 * The bindings are regenerated by `wails3 generate bindings` and are not
 * checked in.
 */

import * as AppServiceBindings from '../../bindings/github.com/incurl/aurore/bindings/appservice';
import * as JobsModels from '../../bindings/github.com/incurl/aurore/jobs/models';
import * as BindingsModels from '../../bindings/github.com/incurl/aurore/bindings/models';
import * as PocketBaseModels from '../../bindings/github.com/incurl/aurore/pocketbase/models';

import type { GenerationRequest } from '../invoke-adapter/types';

// The generated model classes are the source of truth for the shapes that
// cross the Wails boundary. The status and kind fields are narrowed to
// literal unions here, at the single point where the raw generated types
// enter the application.
export type Asset = JobsModels.Asset & { kind: 'reference' | 'mask' };
export type Image = JobsModels.Image;
export type Job = JobsModels.Job & {
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  // The bindings are generated as interfaces, where a missing array is
  // typed as nullable. The backend always sends an array, so it is
  // normalised here.
  image_ids: string[];
};
export type Preset = JobsModels.Preset;
export type Request = JobsModels.Request;
export type Params = JobsModels.Params;
export type Capabilities = BindingsModels.Capabilities & {
  aspect_ratios: string[];
  style_types: string[];
};
export type SettingsView = BindingsModels.SettingsView;
export type Defaults = PocketBaseModels.Defaults;

/**
 * The application settings as seen by the UI.
 *
 * The API key is never returned by the backend, only its presence.
 */
export type Settings = {
  has_api_key: boolean;
  base_url: string;
  model: string;
  defaults: Defaults;
};

/**
 * The Wails event name emitted when a job changes state.
 */
export const EVENT_JOB_UPDATED = 'job:updated';

/**
 * Submits a generation job.
 */
export function submitJob(request: GenerationRequest): Promise<Job> {
  return AppServiceBindings.SubmitJob(request as never) as unknown as Promise<Job>;
}

/**
 * Cancels a pending or running job.
 */
export function cancelJob(jobId: string): Promise<void> {
  return AppServiceBindings.CancelJob(jobId) as Promise<void>;
}

/**
 * Re-runs a job with the same parameters.
 */
export function retryJob(jobId: string): Promise<Job> {
  return AppServiceBindings.RetryJob(jobId) as unknown as Promise<Job>;
}

/**
 * Lists the recent jobs.
 */
export async function listJobs(limit = 50): Promise<Job[]> {
  const jobs = (await AppServiceBindings.ListJobs(limit)) as unknown as JobsModels.Job[];
  return jobs.map(normaliseJob);
}

/**
 * Normalises a job so that the collections it carries are always arrays.
 */
function normaliseJob(job: JobsModels.Job): Job {
  return {
    ...job,
    status: job.status as Job['status'],
    image_ids: job.image_ids ?? [],
  };
}

/**
 * Returns a single job.
 */
export async function getJob(jobId: string): Promise<Job> {
  return normaliseJob((await AppServiceBindings.GetJob(jobId)) as unknown as JobsModels.Job);
}

/**
 * Lists the generated images, optionally filtered by job.
 */
export function listImages(jobId = '', limit = 100): Promise<Image[]> {
  return AppServiceBindings.ListImages(jobId, limit) as unknown as Promise<Image[]>;
}

/**
 * Deletes a generated image.
 */
export function deleteImage(imageId: string): Promise<void> {
  return AppServiceBindings.DeleteImage(imageId) as Promise<void>;
}

/**
 * Stores an uploaded reference image or mask.
 *
 * Byte slices cross the Wails boundary as base64 encoded strings.
 */
export function uploadAsset(
  kind: 'reference' | 'mask',
  data: Uint8Array,
  filename: string,
): Promise<Asset> {
  const encoded = base64FromBytes(data);
  return AppServiceBindings.UploadAsset(kind, encoded, filename) as unknown as Promise<Asset>;
}

/**
 * Lists the uploaded assets.
 */
export function listAssets(kind = '', limit = 50): Promise<Asset[]> {
  return AppServiceBindings.ListAssets(kind, limit) as unknown as Promise<Asset[]>;
}

/**
 * Deletes an uploaded asset.
 */
export function deleteAsset(assetId: string): Promise<void> {
  return AppServiceBindings.DeleteAsset(assetId) as Promise<void>;
}

/**
 * Lists the saved prompt presets.
 */
export function listPresets(): Promise<Preset[]> {
  return AppServiceBindings.ListPresets() as unknown as Promise<Preset[]>;
}

/**
 * Creates or updates a prompt preset.
 */
export function savePreset(preset: Preset): Promise<Preset> {
  return AppServiceBindings.SavePreset(preset as never) as unknown as Promise<Preset>;
}

/**
 * Deletes a prompt preset.
 */
export function deletePreset(presetId: string): Promise<void> {
  return AppServiceBindings.DeletePreset(presetId) as Promise<void>;
}

/**
 * Returns the application settings. The API key is never included.
 */
export function getSettings(): Promise<Settings> {
  return AppServiceBindings.GetSettings() as unknown as Promise<Settings>;
}

/**
 * Stores the MiniMax credentials. An empty apiKey keeps the stored key.
 */
export function saveCredentials(
  apiKey: string,
  baseUrl: string,
  model: string,
): Promise<void> {
  return AppServiceBindings.SaveCredentials(apiKey, baseUrl, model) as Promise<void>;
}

/**
 * Stores the default generation preferences.
 */
export function saveDefaults(defaults: Settings['defaults']): Promise<void> {
  return AppServiceBindings.SaveDefaults(defaults as never) as Promise<void>;
}

/**
 * Verifies the stored MiniMax credentials without generating an image.
 */
export function testCredentials(): Promise<void> {
  return AppServiceBindings.TestCredentials() as Promise<void>;
}

/**
 * Returns the capability description for a model.
 */
export async function getCapabilities(model = ''): Promise<Capabilities> {
  const capabilities = (await AppServiceBindings.GetCapabilities(model)) as unknown as BindingsModels.Capabilities;
  return {
    ...capabilities,
    aspect_ratios: capabilities.aspect_ratios ?? [],
    style_types: capabilities.style_types ?? [],
  };
}

/**
 * Returns the bytes of a generated image so it can be saved to disk.
 */
export async function exportImage(imageId: string): Promise<Uint8Array> {
  const encoded = (await AppServiceBindings.ExportImage(imageId)) as unknown as string;
  return base64ToBytes(encoded);
}

/**
 * Encodes raw bytes as base64.
 */
function base64FromBytes(bytes: Uint8Array): string {
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
  }
  return btoa(binary);
}

/**
 * Decodes a base64 string into raw bytes.
 */
function base64ToBytes(encoded: string): Uint8Array {
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * The generated model classes, re-exported for callers that need them.
 */
export { JobsModels, BindingsModels, PocketBaseModels };
